e-columns:92px 1fr;min-height:340px;border:1px solid rgba(150,175,220,.12);border-radius:13px;overflow:hidden;background:#090e18}.side{padding:15px 10px;border-right:1px solid rgba(150,175,220,.1)}.side-brand{font-size:8px;letter-spacing:.16em;color:#8da7d2;margin-bottom:24px}.side-item{padding:8px 7px;border-radius:7px;color:#73829d;font-size:9px;margin:5px 0}.side-item.active{color:#dce8ff;background:rgba(65,125,255,.16);border:1px solid rgba(65,125,255,.19)}.dash{padding:18px 17px}.dash-head{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:17px}.dash-head strong{font:600 15px 'Space Grotesk',sans-serif}.live{font-size:8px;color:#8de3bb;border:1px solid rgba(127,224,178,.22);background:rgba(127,224,178,.06);border-radius:99px;padding:4px 7px}.stat-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.stat{padding:10px;border:1px solid rgba(150,175,220,.12);border-radius:9px;background:rgba(255,255,255,.018)}.stat label{display:block;color:#7f8eaa;font-size:8px}.stat strong{display:block;font:600 18px 'Space Grotesk',sans-serif;margin:4px 0}.stat small{font-size:8px;color:#7fe0b2}.chart-card{margin-top:10px;border:1px solid rgba(150,175,220,.12);border-radius:9px;padding:12px}.chart-head{display:flex;justify-content:space-between;color:#9eacc3;font-size:9px}.chart-head strong{color:#e8efff}.chart{width:100%;height:98px;margin-top:8px}.chart-grid{stroke:rgba(151,176,219,.12);stroke-width:1}.chart-line{fill:none;stroke:#53d8eb;stroke-width:2.5;stroke-linecap:round;stroke-linejoin:round}.chart-area{fill:url(#area)}.activity{display:grid;grid-template-columns:1fr auto;gap:8px;margin-top:11px;font-size:9px;color:#91a0b9}.activity span:last-child{color:#7fe0b2}.float-chip{position:absolute;right:-20px;bottom:25px;padding:12px 14px;background:#101b2a;border:1px solid rgba(84,227,240,.25);border-radius:12px;box-shadow:0 15px 35px #05080f;color:#dbeaff;font-size:10px}.float-chip b{display:block;font-size:12px;margin-bottom:3px}.f