e)}.layer:last-child{border-bottom:0}.layer-no{font:600 12px 'Space Grotesk',sans-serif;color:#5f8fff}.layer b{display:block;font-size:13px}.layer small{display:block;color:#8d9db7;font-size:11px;margin-top:3px}.layer-tag{font-size:9px;color:#a4c9ff;border:1px solid rgba(100,151,255,.22);padding:5px 7px;border-radius:7px}.principles{display:grid;gap:19px;margin-top:26px}.principle{display:flex;gap:13px;align-items:flex-start}.check{flex:none;width:23px;height:23px;border:1px solid rgba(127,224,178,.23);border-radius:8px;color:var(--green);display:grid;place-items:center;font-size:12px}.principle b{display:block;font-size:13px;margin-bottom:3px}.principle span{display:block;color:#94a3bc;font-size:12px;line-height:1.65}.roles{display:grid;grid-template-columns:repeat(3,1fr);gap:15px}.role{padding:22px;border:1px solid var(--line);border-radius:16px;background:rgba(15,22,35,.65)}.role small{color:#6bdbe8;font-size:10px;text-transform:uppercase;letter-spacing:.14em;font-weight:700}.role h3{font-size:21px;margin:11px 0}.role p{font-size:13px;color:#98a7bf;line-height:1.75;margin:0}.cta{padding:42px;border-radius:22px;border:1px solid rgba(87,154,255,.25);background:radial-gradient(ellipse at 90% 0%,rgba(53,116,237,.19),transparent 40%),linear-gradient(120deg,#101b2b,#0b111c);display:flex;align-items:center;justify-content:space-between;gap:25px}.cta h2{font-size:clamp(27px,3vw,37px);margin-bottom:10px}.cta p{color:#a0aec6;margin:0;font-size:14px}.faq{display:grid;grid-template-columns:.7fr 1.3fr;gap:50px}.faq-list details{border-bottom:1px solid var(--line);padding:17px 0}.faq-list summary{cursor:pointer;font-weight:600;font-size:14px;list-style:none;display:flex;justify-content:space-between;gap:15px}.faq-list summary::-webkit-details-marker{display:none}.faq-list summary:after{content:"+";color:var(--cyan);font-size:20px;line-height:1}.faq-list details[open] summary:after{content:"−"}.faq-list p{color:#9baac2;font-size:13px;line-height:1.8;margin:13px 25px 0 0}.footer