                            <div class="chart-head"><strong>Network activity</strong><span>Illustrative view</span></div>
                            <svg class="chart" viewBox="0 0 400 100" preserveAspectRatio="none" role="img" aria-label="Decorative network activity chart"><defs><linearGradient id="area" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#53d8eb" stop-opacity=".25"/><stop offset="1" stop-color="#53d8eb" stop-opacity="0"/></linearGradient></defs><path class="chart-grid" d="M0 15H400M0 40H400M0 65H400M0 90H400"/><path class="chart-area" d="M0 77 L24 69 L48 73 L72 48 L96 56 L120 39 L144 51 L168 28 L192 43 L216 34 L240 55 L264 24 L288 35 L312 19 L336 31 L360 12 L384 25 L400 17 L400 100 L0 100Z"/><path class="chart-line" d="M0 77 L24 69 L48 73 L72 48 L96 56 L120 39 L144 51 L168 28 L192 43 L216 34 L240 55 L264 24 L288 35 L312 19 L336 31 L360 12 L384 25 L400 17"/></svg>
                        </div>
